import{createNativeScene,actor,putKey,validateScene}from'./scene.js';
export function createFinalHandshake(){const s=createNativeScene('empty');s.name='15:00 handshake · V93 anatomical actors';s.duration=6;s.sourceOffset=900;s.background='#0b2033';s.lighting.ambient=.3;s.nodes=s.nodes.filter(n=>n.id!=='floor');const blue=actor('final-blue','Blue partner','#167caf',[-.65,0,0]),coach=actor('final-coach','Cream partner','#e5e0cc',[.65,0,0]);blue.rotation=[0,90,0];coach.rotation=[0,-90,0];coach.parts.hat.visible=true;coach.parts.hat.autoFit=true;for(const n of[blue,coach]){n.proportions.headSize=1;n.handCurl={L:.12,R:.2};n.shape={pelvis:-.08,glutes:-.08};n.ikTracks={rightHand:[{time:0,value:[n.position[0],.85,.15]},{time:.8,value:[0,1.05,.35]},{time:1.4,value:[0,1.09,.35]},{time:1.9,value:[0,1.03,.35]},{time:2.4,value:[0,1.08,.35]},{time:2.9,value:[n.position[0],.85,.15]}]};s.nodes.push(n);}const camera=s.nodes.find(n=>n.id===s.cameraId);camera.position=[0,1.4,4.3];camera.target=[0,1.05,0];camera.fov=32;putKey(camera,'position',0,[0,1.4,4.3]);putKey(camera,'position',1.05,[0,1.15,2.9]);putKey(camera,'position',2.4,[0,1.4,4.3]);putKey(camera,'target',3,[0,1.05,0]);putKey(camera,'target',5.5,[0,4.3,0]);validateScene(s);return s;}
export function createFinalTeam(){const s=createNativeScene('empty');s.name='Three independent red anatomical players';s.transparentBackground=true;s.duration=6;s.sourceOffset=915;s.background='#08090b';s.lighting.ambient=.06;s.nodes=s.nodes.filter(n=>n.id!=='floor');for(let i=0;i<3;i++){const n=actor('final-player-'+i,'Red player '+(i+1),'#b71326',[(i-1)*.65,0,i===1?0:.2]);n.proportions.headSize=1;n.headColor='#b71326';n.parts.shirt.color='#b71326';n.parts.trousers.color='#b71326';n.handCurl={L:.15,R:.16};n.boneTracks={head:[{time:0,value:[0,(i-1)*-8,0]},{time:6,value:[0,(i-1)*-6,0]}]};s.nodes.push(n);}const camera=s.nodes.find(n=>n.id===s.cameraId);camera.position=[.3,1.2,4.8];camera.target=[0,1,0];camera.fov=33;putKey(camera,'position',0,[.4,1.2,5.2]);putKey(camera,'position',6,[0,1.2,4.5]);s.nodes.find(n=>n.id==='key').intensity=.6;s.nodes.find(n=>n.id==='rim').color='#ffb34f';s.nodes.find(n=>n.id==='rim').intensity=3;validateScene(s);return s;}
